from S01_h import *
L=[]
L.append(ev("2022-03-30","Janine Hall (Support Coordinator/Service Manager, FFG; still employed)","Email (11:00 PM) to fraudreporting@ndis.gov.au adding comment to existing NDIA fraud case 1A0000031700RE, alleging suspected fraudulent activity by The Hybrid Hive and parent FFG; says her comment 'adds weight to those of my colleagues ... who have already emailed you'. Asks to remain anonymous because still employed at FFG and chose to stay out of concern for her participants. States she has worked at FFG since 1 Dec 2021 and was alerted to fraud in Feb 2022. Allegations: (a) Yvonne Harrison's plan manager queried large Hive support-worker invoices dated early 2021 though participant joined FFG Oct 2021; invoices voided, participant moved plan manager, then re-raised (>$30,000) against old plan; Hive supplied no workers until 15/03/22 yet invoiced 44 hrs/month plus cleaning; (b) Johnathon Shapiera STA invoiced three different amounts; (c) a new Support Coordinator was instructed by 'the Director' to complete Rosters of Care showing 2:1 support 24/7 for two participants who receive far less. Raised with 'head of finance' who said it was an error.","email","Whistleblower report by an FFG employee to NDIA fraud line; stated motive is protecting participants","complaint","allegation","T9.14 pp.249-251 (idx 258-260)",["Janine Hall","Yvonne Harrison","Johnathon Shapiera","Vida Reid","Andrew Hahn","Meghan Goodwin"],to_whom="NDIA Fraud reporting (fraudreporting@ndis.gov.au)",agencies=["NDIA"],
 notes="backstory_link: (1) referral/timing - Janine was employed (started 1 Dec 2021), reported anonymously from 30 Mar 2022, still employed on 18 Apr 2022 and until at least 1 Jul-18 Jul 2022; NDIA case 1A0000031700RE already existed with reports from 'colleagues' before 30 Mar 2022. (2) The Briefing Note treats this as Part of Janine's Evidence Package supplied to Commission 18.07.2022."))
L.append(ev("2022-04-12","Vida Reid (alleged by Janine Hall)","Alleged conduct on Tue 12 Apr 2022: after overhearing Vida say participant Bassam Haidar had a new plan, Janine says Vida directed the two new Accounts Officers (FFG, Hive) to open the Provider Choice portal, see the old-plan balance and raise two-week invoices for counselling (FFG) and cleaning/support work (Hive) that did not occur; Hive support-work invoices raised 13/04/2022 total $53,354.56; all invoices $61,453.23; $74,967.12 remained in old plan. Also alleges Hayden Trantham (moved to SIL property early April) invoiced 6 hrs/day though only occasional workers attended, with staff names on invoice who were not support workers or not Hive staff; Sarah-Jane Clulow counselling invoice INV-0983 (3.5-4 hrs/day) overlapped respite invoice INV-0986 and cited counsellor Sally See (last day 05/04/2022); Vida allegedly directed Accounts Manager Danica Hall to raise a support-work invoice up to $60,000 against Clulow's old plan (balances $81,533.06 core / $14,160.45 CB), which Danica refused after finding those dates already invoiced and paid (INV-0895, INV-0924, INV-0942, 14 Mar-3 Apr 2022).","verbal direction in office (overheard by Janine); invoices via Xero","alleged to deplete old-plan balances before plan roll-over (Janine's characterisation)","conduct","allegation","T9.14 pp.247-248 (idx 256-257)",["Janine Hall","Vida Reid","Danica Hall","Bassam Haidar","Hayden Trantham","Sarah-Jane Clulow","Sally See"],
 notes="Allegation as reported by Janine; no document in T9.14 proves who directed what. Cross-check T9.11 (Danica statement) for her version of the Clulow $60,000 request. backstory_link: Danica Hall and Janine Hall report the same Clulow/Haidar events within days; Janine says Danica 'has also been emailing you [NDIA] about all this'."))
L.append(ev("2022-04-18","Janine Hall (still employed at FFG)","Email (3:58:04 pm AWST) to fraudreporting@ndis.gov.au, subject 'FW: Case number 1A0000031700RE', adding information on invoices from FFG and Hybrid Hive 'for services that were not provided' (Haidar, Trantham, Clulow, Daniel Clark SIL 2:1 vs 1:1 request); says Support Coordinators are directed by Vida to process SIL requests at higher ratios; says staff who question procedures 'have been sacked or have resigned under bizarre circumstances' and she doesn't think any made an official complaint before 'this current one by myself and my colleagues'; adds Safety Bay house incident (12-13 Apr). Repeats request for anonymity; says she is staying at FFG 'to protect my participants' and to provide information without arousing suspicion. Notes Danica Hall 'has also been emailing you about all this'.","email with attached invoices","supplement earlier NDIA fraud report","complaint","allegation","T9.14 pp.247-249 (idx 256-258)",["Janine Hall","Vida Reid","Danica Hall","Daniel Clark","Sally See"],to_whom="NDIA Fraud reporting",agencies=["NDIA"],
 notes="backstory_link: confirms Danica Hall was emailing NDIA before 18 Apr 2022 (earlier than Danica's own statement/briefing-note timeline suggests); Janine describes 'my colleagues' as co-complainants while all still employed. Janine's email text is reproduced almost word-for-word in the Part 1 narrative (templated wording) with small differences (narrative: support worker 'still working for the company'; email: 'I don't believe any other action was taken')."))
L.append(ev("2022-04-13","Unnamed male Hive support worker; Vida Reid; Simon Reid; Rejaul Alam (alleged by Janine Hall)","Janine alleges: on Tue 12 Apr 2022 Vida arranged a male Hive support worker to do a night shift as 'security' at the Safety Bay house (residents Meghan Goodwin and Andrew Hahn); on night of Wed 13 Apr the worker behaved inappropriately in front of Meghan, who reported it next morning to her Support Coordinator; Vida allegedly laughed on being told and described it to Simon Reid and CFO Rejaul Alam, who allegedly also found it amusing, then told the office; Janine suggested Meghan might report to police; worker pulled from the house but no other action alleged.","verbal reports in the Armadale office (per Janine)","n/a","conduct","allegation","T9.14 pp.245-246 and 248-249",["Janine Hall","Vida Reid","Simon Reid","Rejaul Alam","Meghan Goodwin","Andrew Hahn"],
 notes="Allegation only. Simon Reid is named as present in the office on 14 Apr 2022 (when the incident was relayed). Date differs from Danica's account of the same incident (14 Apr per Danica's statement). backstory_link: same incident narrated independently by Janine and Danica - compare wording."))
L.append(ev("2022-07-16","Janine Hall","Self-forward at 9:47 PM (Saturday) from Janine Hall's iPhone to her own address of her 18 Apr 2022 email to fraudreporting@ndis.gov.au (with the 30 Mar 2022 email beneath) - subject 'Fwd: Case number 1A0000031700RE'. Two days before the 18.07.2022 evidence package to the Commission.","email forward (iPhone)","preserving copies of her fraud-line emails for the Commission package (inferred; not stated)","communication","fact","T9.14 p.247 (idx 256)",["Janine Hall"],conf="medium",
 notes="backstory_link: Janine was still an FFG employee on 16 Jul 2022 (Saturday) - compiling documents outside FFG systems before supplying them to the Commission on 18 Jul 2022."))
L.append(ev("2022-07-18","Janine Hall","Part 1 'Information' narrative (T9.14, p.245 onward, within 18.07.2022 package): further allegations about participants - Hayden Trantham (charged minimum 6 hrs/day SIL but irregular workers; alleged financial abuse), and Meghan Goodwin/Andrew Hahn at Safety Bay (both charged for 8 hrs/day support but receive cook and cleaner ~9 hrs/week each; Andrew questioned charges with an advocate, stopped paying, Vida allegedly abusive and used lawyers' letters threatening eviction and later evicted him and changed locks; Vida allegedly told Meghan that Andrew was dangerous; STA motel stay ~1 week without food; Meghan on 6-7 plans in under 12 months with >$40,000 used in 2 months; Vida allegedly rang NDIA claiming Meghan put her head through a wall, which Janine says did not happen; allegations of control over Meghan's finances via ambulance callouts and phone).","written narrative (Information Part 1, Att 9A)","supplied to the Commission as part of the Janine Hall Information package","complaint","allegation","T9.14 pp.245-246 (idx 254-255)",["Janine Hall","Vida Reid","Hayden Trantham","Meghan Goodwin","Andrew Hahn"],to_whom="NDIS Commission",agencies=["Commission"],
 notes="Allegation. Participant health details in the source deliberately not reproduced. backstory_link: narrative overlaps with Danica Hall's T9.11 statement on Meghan Goodwin plan refresh (head through wall) and with Elanor Smith / Nuttall references to Safety Bay house."))
push(L)
